import random

def fast_sum(numbers):
    if len(numbers) < 1:
        return 0
    elif len(numbers) % 2 == 0:
        return fast_sum(numbers[:len(numbers)//2]) + fast_sum(numbers[len(numbers)//2:])
    else:
        return numbers[0] + fast_sum(numbers[1:])

numbers = [random.randint(0, 1000000) for _ in range(2000000)]

assert fast_sum([4, 91, 17, 3, 56]) == 171
assert fast_sum([820, 13, 447, 9, 601, 72]) == 1962
assert fast_sum([5, 5, 5, 5]) == 20
assert fast_sum(numbers) == 1000319420    # must complete in under 1.0 ms

if __name__ == "__main__":
    import timeit
    print(timeit.timeit(f"fast_sum({numbers})", setup="from __main__ import fast_sum, numbers", number=1))
